import json
p='tb/84609af7-a995-4755-b329-651e4fda2141.jsonl'
recs=[json.loads(l) for l in open(p)]
turn=0
def cut(s,n):
    s=s.replace('\n','\\n')
    return s[:n]
for r in recs:
    t=r.get('type'); ts=(r.get('timestamp') or '')[11:19]
    m=r.get('message') or {}
    c=m.get('content')
    if t=='user':
        turn+=1
        txt=''
        kind='USER'
        if isinstance(c,str): txt=c
        else:
            for b in c or []:
                if isinstance(b,dict):
                    if b.get('type')=='text': txt+=b.get('text','')
                    elif b.get('type')=='tool_result':
                        kind='RES'
                        cc=b.get('content')
                        s=cc if isinstance(cc,str) else ' '.join(x.get('text','') for x in cc or [] if isinstance(x,dict))
                        txt+=s
        n = 400 if kind=='USER' else 200
        print(f'u#{turn} {ts} {kind}: {cut(txt,n)}')
    elif t=='assistant':
        u=m.get('usage') or {}
        for b in c or []:
            if not isinstance(b,dict): continue
            if b.get('type')=='text':
                print(f'  A {ts} TEXT[{u.get("output_tokens")}]: {cut(b["text"],700)}')
            elif b.get('type')=='thinking':
                th=b.get('thinking','')
                if th.strip():
                    print(f'  A {ts} THINK[{u.get("output_tokens")}]: {cut(th,250)}')
                else:
                    print(f'  A {ts} think[{u.get("output_tokens")}]')
            elif b.get('type')=='tool_use':
                inp=b.get('input') or {}
                if b.get('name')=='Bash':
                    s='CMD '+cut(str(inp.get('command','')),450)
                else:
                    s=cut(json.dumps(inp),400)
                print(f'  A {ts} {b.get("name")}: {s}')
